/* Answer the usbbus.open_interface request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t usbbus_reply_open_interface(struct idl_txn idl_txn, status_t idl_st, handle_t channel)
{
    struct usbbus_open_interface_rep idl_r;
    handle_t idl_hs[1] = { channel };
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(channel != HANDLE_INVALID))
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK) {
        if (idl_hs[0] != HANDLE_INVALID)
            drv_handle_close(idl_hs[0]);
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    }
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), idl_hs, 1);
}

/* Answer the usbbus.interface_attached request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t usbbus_reply_interface_attached(struct idl_txn idl_txn, status_t idl_st)
{
    struct usbbus_interface_attached_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (USBBUS_REP_MAX bytes) and the handles it carries
 * into rhs (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it can't. */
static inline uint32_t usbbus_dispatch_on(handle_t ch, const struct usbbus_ops *ops, void *ctx,
                                          const void *req, uint32_t n, void *rep, handle_t *rhs,
                                          uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case USBBUS_STATUS: {
        const struct usbbus_status_req *idl_q = (const struct usbbus_status_req *)req;
        struct usbbus_status_rep *idl_r = (struct usbbus_status_rep *)rep;
        uint32_t out_devices = 0;
        uint32_t out_hubs = 0;
        uint32_t out_interfaces = 0;
        uint32_t out_hid_interfaces = 0;
        uint32_t out_problems = 0;
        uint32_t out_generation = 0;
        uint8_t out_settled = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->status) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->status(ctx, &out_devices, &out_hubs, &out_interfaces, &out_hid_interfaces, &out_problems, &out_generation, &out_settled);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->devices = out_devices;
        idl_r->hubs = out_hubs;
        idl_r->interfaces = out_interfaces;
        idl_r->hid_interfaces = out_hid_interfaces;
        idl_r->problems = out_problems;
        idl_r->generation = out_generation;
        idl_r->settled = out_settled;
        return sizeof(*idl_r);
    }
    case USBBUS_WAIT_SETTLED: {
        const struct usbbus_wait_settled_req *idl_q = (const struct usbbus_wait_settled_req *)req;
        struct usbbus_wait_settled_rep *idl_r = (struct usbbus_wait_settled_rep *)rep;
        uint32_t out_devices = 0;
        uint32_t out_hubs = 0;
        uint32_t out_interfaces = 0;
        uint32_t out_hid_interfaces = 0;
        uint32_t out_problems = 0;
        uint32_t out_generation = 0;
        uint8_t out_settled = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->wait_settled) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->wait_settled(ctx, idl_q->timeout_ms, &out_devices, &out_hubs, &out_interfaces, &out_hid_interfaces, &out_problems, &out_generation, &out_settled);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->devices = out_devices;
        idl_r->hubs = out_hubs;
        idl_r->interfaces = out_interfaces;
        idl_r->hid_interfaces = out_hid_interfaces;
        idl_r->problems = out_problems;
        idl_r->generation = out_generation;
        idl_r->settled = out_settled;
        return sizeof(*idl_r);
    }
    case USBBUS_DEVICE: {
        const struct usbbus_device_req *idl_q = (const struct usbbus_device_req *)req;
        struct usbbus_device_rep *idl_r = (struct usbbus_device_rep *)rep;
        uint32_t out_id = 0;
        uint32_t out_parent_id = 0;
        uint16_t out_vendor = 0;
        uint16_t out_product = 0;
        uint16_t out_bcd_usb = 0;
        uint8_t out_speed = 0;
        uint8_t out_address = 0;
        uint8_t out_slot = 0;
        uint8_t out_root_port = 0;
        uint8_t out_port = 0;
        uint8_t out_level = 0;
        uint32_t out_route = 0;
        uint8_t out_tt_slot = 0;
        uint8_t out_tt_port = 0;
        uint8_t out_class_code = 0;
        uint8_t out_subclass = 0;
        uint8_t out_protocol = 0;
        uint8_t out_num_configs = 0;
        uint8_t out_configuration = 0;
        uint8_t out_num_interfaces = 0;
        uint16_t out_max_packet0 = 0;
        uint8_t out_hub_ports = 0;
        uint8_t out_path[24];
        for (uint32_t idl_i = 0; idl_i < 24; idl_i++)
            out_path[idl_i] = 0;
        uint8_t out_product_name[40];
        for (uint32_t idl_i = 0; idl_i < 40; idl_i++)
            out_product_name[idl_i] = 0;
        uint8_t out_serial[24];
        for (uint32_t idl_i = 0; idl_i < 24; idl_i++)
            out_serial[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->device) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->device(ctx, idl_q->index, &out_id, &out_parent_id, &out_vendor, &out_product, &out_bcd_usb, &out_speed, &out_address, &out_slot, &out_root_port, &out_port, &out_level, &out_route, &out_tt_slot, &out_tt_port, &out_class_code, &out_subclass, &out_protocol, &out_num_configs, &out_configuration, &out_num_interfaces, &out_max_packet0, &out_hub_ports, out_path, out_product_name, out_serial);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->id = out_id;
        idl_r->parent_id = out_parent_id;
        idl_r->vendor = out_vendor;
        idl_r->product = out_product;
        idl_r->bcd_usb = out_bcd_usb;
        idl_r->speed = out_speed;
        idl_r->address = out_address;
        idl_r->slot = out_slot;
        idl_r->root_port = out_root_port;
        idl_r->port = out_port;
        idl_r->level = out_level;
        idl_r->route = out_route;
        idl_r->tt_slot = out_tt_slot;
        idl_r->tt_port = out_tt_port;
        idl_r->class_code = out_class_code;
        idl_r->subclass = out_subclass;
        idl_r->protocol = out_protocol;
        idl_r->num_configs = out_num_configs;
        idl_r->configuration = out_configuration;
        idl_r->num_interfaces = out_num_interfaces;
        idl_r->max_packet0 = out_max_packet0;
        idl_r->hub_ports = out_hub_ports;
        for (uint32_t idl_i = 0; idl_i < 24; idl_i++)
            idl_r->path[idl_i] = out_path[idl_i];
        for (uint32_t idl_i = 0; idl_i < 40; idl_i++)
            idl_r->product_name[idl_i] = out_product_name[idl_i];
        for (uint32_t idl_i = 0; idl_i < 24; idl_i++)
            idl_r->serial[idl_i] = out_serial[idl_i];
        return sizeof(*idl_r);
    }
    case USBBUS_INTERFACE: {
        const struct usbbus_interface_req *idl_q = (const struct usbbus_interface_req *)req;
        struct usbbus_interface_rep *idl_r = (struct usbbus_interface_rep *)rep;
        uint8_t out_number = 0;
        uint8_t out_alt_setting = 0;
        uint8_t out_num_alt_settings = 0;
        uint8_t out_class_code = 0;
        uint8_t out_subclass = 0;
        uint8_t out_protocol = 0;
        uint8_t out_num_endpoints = 0;
        uint8_t out_endpoints[8];
        for (uint32_t idl_i = 0; idl_i < 8; idl_i++)
            out_endpoints[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->interface) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->interface(ctx, idl_q->id, idl_q->index, &out_number, &out_alt_setting, &out_num_alt_settings, &out_class_code, &out_subclass, &out_protocol, &out_num_endpoints, out_endpoints);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->number = out_number;
        idl_r->alt_setting = out_alt_setting;
        idl_r->num_alt_settings = out_num_alt_settings;
        idl_r->class_code = out_class_code;
        idl_r->subclass = out_subclass;
        idl_r->protocol = out_protocol;
        idl_r->num_endpoints = out_num_endpoints;
        for (uint32_t idl_i = 0; idl_i < 8; idl_i++)
            idl_r->endpoints[idl_i] = out_endpoints[idl_i];
        return sizeof(*idl_r);
    }
    case USBBUS_OPEN_INTERFACE: {
        const struct usbbus_open_interface_req *idl_q = (const struct usbbus_open_interface_req *)req;
        struct usbbus_open_interface_rep *idl_r = (struct usbbus_open_interface_rep *)rep;
        handle_t out_channel = HANDLE_INVALID;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->open_interface) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->open_interface(ctx, idl_q->id, idl_q->interface_number, &out_channel);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_channel != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_channel != HANDLE_INVALID)
                drv_handle_close(out_channel);
            return sizeof(*idl_h);
        }
        rhs[0] = out_channel;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case USBBUS_INTERFACE_ATTACHED: {
        const struct usbbus_interface_attached_req *idl_q = (const struct usbbus_interface_attached_req *)req;
        struct usbbus_interface_attached_rep *idl_r = (struct usbbus_interface_attached_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->interface_attached) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->interface_attached(ctx, idl_q->id, idl_q->vendor, idl_q->product, idl_q->interface_number, idl_q->class_code, idl_q->subclass, idl_q->protocol, idl_q->speed, idl_q->path);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* usbbus_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t usbbus_dispatch(const struct usbbus_ops *ops, void *ctx, const void *req, uint32_t n,
                                       void *rep, handle_t *rhs, uint32_t *rhn)
{
    return usbbus_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request: ERR_INVALID_ARGS if it has less. */
static inline status_t usbbus_take_slot(handle_t ch, const struct idl_slot *slot)
{
    if (slot->qcap < USBBUS_REQ_MAX)
        return ERR_INVALID_ARGS;
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by usbbus_take_slot, or found there by a
 * successor), which came on ch: as usbbus_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (IDL_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it can't. */
static inline uint32_t usbbus_run_slot(handle_t ch, const struct idl_slot *slot,
                                       const struct usbbus_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return usbbus_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. */
static inline bool usbbus_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t usbbus_serve_one(handle_t ch, const struct usbbus_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[USBBUS_REQ_MAX];
    _Alignas(8) uint8_t idl_r[USBBUS_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = usbbus_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t usbbus_serve(handle_t ch, const struct usbbus_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[USBBUS_REQ_MAX];
    _Alignas(8) uint8_t idl_r[USBBUS_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = usbbus_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
